-- (after re-apply) Frontend ↔ prod drift (read-only): RPCs and tables referenced in korehan/*
-- that do not exist in the database, plus the room/shop objects.
with rpc(n) as (select unnest(array['accept_friend_request','admin_adjust_coin','admin_resolve_report','admin_set_suspension','aggregate_claude_costs_daily','award_xp','block_user','buy_room_item','check_anthropic_budget_alert','claim_streak_award','cleanup_old_read_notifications','complete_onboarding','consume_streak_freeze','draw_gacha','finish_read_event','get_blocked_users','get_freeze_inventory','get_friend_list','get_live_zoom_link','get_pending_friend_requests','get_playground_leaderboard','get_recent_speaking_scores','get_recent_wpm','get_recent_writing_rubric','increment_ft_play_count','increment_srs_review_count','inspect_public_tables','inspect_table_columns','kh_db_size_overview','log_playground_score','log_quiz_result','log_read_event','mark_conv_scenario_used','mark_feedback_viewed','mark_notifications_read','merge_grammar_progress','newsletter_confirm','newsletter_unsubscribe','newsletter_unsubscribe_by_token','notify_admin_cache_miss','notify_comment_reply','pick_conv_scenario','post_guestbook','purchase_coin_shop_item','record_grammar_attempt','refresh_user_station_progress','reject_friend_request','report_content','report_sentence_analysis','save_daily_content_if_missing','save_or_update_word','save_placement_result','send_friend_request','send_reporter_gift','set_equipped_cosmetic','soft_delete_comment','submit_comment','unblock_user'])),
     tbl(n) as (select unnest(array['app_settings','article_cache','article_study_content','article_views','articles','articles_data','avatars','badges','bookmarks','cast_characters','character_reporters','claude_cost_by_feature_month','claude_cost_daily','client_errors','coin_adjustments','coin_transactions','comment_reactions','comments','content_reports','content_station_map','conv_scenario_pool','conversations_data','curriculum_lines','curriculum_stations','daily_missions','daily_reviews','essential_expressions','fast_track_progress','fast_track_scenarios','friend_requests','friendships','gacha_items','gacha_owned_items','grammar_curriculum','grammar_examples_cache','grammar_label_map','guestbook','hover_vocab_master','korean_slangs','listening_quiz_bank','newsletter_campaigns','newsletter_subs','notifications','owned_items','page_views','payment_orders','phone_calls','playground_scores','profiles','read_articles','reporter_gift_history','reporter_post_images','reporter_posts','reporter_user_affinity','role_characters','room_items','saved_words','sections','sentence_analysis_reports','shop_items','shop_purchases','stories_data','story_series','study_daily_content','study_grammar_progress','study_picture_prompts','study_room_grammar','study_room_helpers','tutor_lessons','tutor_students','user_activity_log','user_badges','user_blocks','user_daily_progress','user_events','user_grammar_stats','user_interests','user_monthly_reports','user_quiz_results','user_read_history','user_room_state','user_saved_phrases','user_saved_stories','user_saved_words','user_sessions','user_station_progress','user_stats','user_story_progress','user_submissions','user_subscriptions','user_weekly_goals','user_weekly_snapshot','vocab_overrides','vocabulary_bank','weekly_live_registrations','weekly_live_sessions','writing_submissions','writing_topics','xp_config','xp_log']))
select json_build_object(
  'missing_rpcs', (select coalesce(json_agg(n order by n), '[]'::json) from rpc
                    where not exists (select 1 from pg_proc p join pg_namespace s on s.oid=p.pronamespace
                                      where s.nspname='public' and p.proname=rpc.n)),
  'missing_tables', (select coalesce(json_agg(n order by n), '[]'::json) from tbl
                    where not exists (select 1 from information_schema.tables t
                                      where t.table_schema in ('public') and t.table_name=tbl.n)),
  'room_state_policies', (select json_agg(policyname) from pg_policies where tablename='user_room_state'),
  'room_items_cols', (select json_agg(column_name) from information_schema.columns where table_schema='public' and table_name='room_items'),
  'room_state_table', to_regclass('public.user_room_state') is not null,
  'buy_room_item_exists', exists(select 1 from pg_proc where proname='buy_room_item'),
  'legacy_room_rows', (select count(*) from public.app_settings where key like 'room_data_%'),
  'coin_tx_cols', (select json_agg(column_name) from information_schema.columns where table_schema='public' and table_name='coin_transactions'),
  'phone_bucket', exists(select 1 from storage.buckets where id='phone-calls'),
  'user_stats_coin_col', (select count(*) from information_schema.columns where table_schema='public' and table_name='user_stats' and column_name='coin_balance')
) as report;
